   "id": "cls-priest",
   "name": "Priest",
   "kind": "combat",
   "summary": "",
   "identity": "Priests are divine martyrs who willingly carry the suffering of others. They intercept wounds, absorb curses, and transform affliction into divine strength. Their miracles grow stronger the more burdens they bear for their allies.",
   "resources": [
    {
     "id": "cls-priest-res-action-points-ap",
     "name": "Action Points (AP)",
     "description": "Extremely limited. Priests rely on deliberate casting and preparation rather than frequent actions. Most of their influence occurs through reactions."
    },
    {
     "id": "cls-priest-res-reaction-points-rp",
     "name": "Reaction Points (RP)",
     "description": "Primary resource for the class. Used to intercept damage, absorb burdens, shield allies, and trigger defensive miracles."
    },
    {
     "id": "cls-priest-res-bonus-points-bp",
     "name": "Bonus Points (BP)",
     "description": "Used sparingly for intense acts of martyrdom, sudden divine intervention, or amplifying protective miracles under extreme pressure."
    }
   ],
